const isTrue = (v) => v === true || String(v).trim().toUpperCase() === 'TRUE';
const rows = $input.all().map(i => i.json);
const nowIso = new Date().toISOString();

const results = [];

for (const row of rows) {
  if (!row.url) continue;

  let status = 'ok';
  let httpCode = null;

  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: row.url,
      timeout: 10000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });

    httpCode = response.statusCode;
    const body = typeof response.body === 'string' ? response.body : String(response.body || '');
    const looksLikeFeed = /<rss[\s>]/i.test(body) || /<feed[\s>]/i.test(body) || /<item[\s>]/i.test(body) || /<entry[\s>]/i.test(body);

    if (httpCode < 200 || httpCode >= 400) {
      status = 'error: http ' + httpCode;
    } else if (!looksLikeFeed) {
      status = 'error: response does not look like valid RSS/Atom';
    }
  } catch (error) {
    status = 'error: ' + (error.message || 'connection failure').slice(0, 200);
  }

  results.push({
    source_name: row.source_name || '',
    url: row.url,
    category: row.category || '',
    active: row.active,
    last_checked: nowIso,
    last_status: status,
    is_broken: status !== 'ok'
  });
}

return results.map(r => ({ json: r }));

const isTrue = (v) => v === true || String(v).trim().toUpperCase() === 'TRUE';
const rows = $input.all().map(i => i.json);

const brokenActive = rows.filter(r => r.is_broken && isTrue(r.active));

return [{
  json: {
    hasBroken: brokenActive.length > 0,
    count: brokenActive.length,
    broken: brokenActive
  }
}];

const data = $json;

const lines = data.broken.map(b => '- ' + (b.source_name || b.url) + '
  ' + b.url + '
  ' + b.last_status);

const text = '⚠️ RSS Sources Health Check — ' + data.count + ' active source(s) with problems:

' + lines.join('

') + '

Check the URL or set active=FALSE in the RSS-Sources tab if it is no longer valid.';

return [{ json: { text } }];

